// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, uint256 msgValue, address sender) public {
        vm.assume(sender != address(0) && sender != address(c));
        msgValue = bound(msgValue, 0, 100 ether);

        uint256 balanceBefore = address(c).balance;

        vm.deal(sender, msgValue);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: msgValue}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));

        if (success) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore + 1 ether);
        }
    }
}
